16	/**
17	 * Crossing a relation, once or as many times as a pattern asks.
18	 *
19	 * A pattern written without a repetition crosses one relation and binds its name to
20	 * it. Written with one, it crosses a chain and binds the same name to the list of
21	 * every relation in the chain — which is what makes `size(e)` the distance between
22	 * two symbols, and what a question like "how far does this controller reach" comes
23	 * down to.
24	 *
25	 * Inside the pattern the name still means one relation at a time, so a predicate
26	 * written on a repeating edge narrows the chain link by link rather than being handed
27	 * a list it would have to unpick. That is GQL's rule, and it is the difference
28	 * between a cheap pattern and an expensive filter after the fact.
29	 *
30	 * @visibility App\Gql\Matching
31	 */
32	final class EdgeMatching
33	{
34	    /**
35	     * @param ElementGraph         $graph      The graph being matched against
36	     * @param ExpressionEvaluation $evaluation How a predicate written in a pattern is worked out
37	     */
38	    public function __construct(
39	        private readonly ElementGraph $graph,
40	        private readonly ExpressionEvaluation $evaluation,
41	    ) {}
42	
43	    /**
44	     * Returns every way a pattern can cross a relation from where it stands.
45	     *
46	     * A repetition allowed to happen no times at all matches without moving, which is
47	     * GQL's rule for a lower bound of zero: the two ends of the pattern turn out to be
48	     * the same symbol.
49	     *
50	     * @param EdgePattern $pattern What the pattern requires of the relation
51	     * @param MatchState  $state   How far the attempt has got
52	     * @param PathMode    $mode    What the path may visit more than once
53	     *
54	     * @example A pattern standing nowhere can cross nothing
55	     *     $matching = new \App\Gql\Matching\EdgeMatching(new \App\Gql\Element\ElementGraph([], [], []), new \App\Gql\Evaluation\ExpressionEvaluation(), 10);
56	     *     $pattern = new \App\Gql\Syntax\Pattern\EdgePattern(\App\Gql\Syntax\Pattern\EdgeDirection::Along);
57	     *     $matching->matches($pattern, \App\Gql\Matching\MatchState::before(\App\Gql\Binding\BindingRow::unit()), \App\Gql\Syntax\Pattern\PathMode::Trail) // => []
58	     *
59	     * @return list<MatchState> The attempts that crossed it
60	     *
61	     * @throws GqlException If a requirement written in the pattern cannot be worked out
62	     */
63	    public function matches(EdgePattern $pattern, MatchState $state, PathMode $mode): array
64	    {
65	        if ($state->current === null) {
66	            return [];
67	        }
68	        $quantifier = $pattern->quantifier;
69	        if ($quantifier === null) {
70	            return $this->crossOnce($pattern, $state, $mode, false);
71	        }
72	
73	        $start = $pattern->variable === null ? $state : $state->bind($pattern->variable, new ListDatum([]));
74	        $reached = $quantifier->allows(0) ? [$start] : [];
75	        $frontier = [$start];
76	        $ceiling = $quantifier->most ?? PHP_INT_MAX;
77	
78	        for ($times = 1; $times <= $ceiling && $frontier !== []; ++$times) {
79	            $next = [];
80	            foreach ($frontier as $standing) {
81	                array_push($next, ...$this->crossOnce($pattern, $standing, $mode, true));
82	            }
83	            $frontier = $next;
84	            if ($quantifier->allows($times)) {
85	                array_push($reached, ...$frontier);
86	            }
87	        }
88	
89	        return $reached;
90	    }
91	
92	    /**
93	     * Returns every way a pattern can cross one relation from where it stands.
94	     *
95	     * @param EdgePattern $pattern   What the pattern requires of the relation
96	     * @param MatchState  $state     How far the attempt has got
97	     * @param PathMode    $mode      What the path may visit more than once
98	     * @param bool        $repeating Whether the name binds to the chain rather than to this relation
99	     *
100	     * @example A pattern standing nowhere can cross nothing
101	     *     $matching = new \App\Gql\Matching\EdgeMatching(new \App\Gql\Element\ElementGraph([], [], []), new \App\Gql\Evaluation\ExpressionEvaluation(), 10);
102	     *     $pattern = new \App\Gql\Syntax\Pattern\EdgePattern(\App\Gql\Syntax\Pattern\EdgeDirection::Along);
103	     *     $matching->crossOnce($pattern, \App\Gql\Matching\MatchState::before(\App\Gql\Binding\BindingRow::unit()), \App\Gql\Syntax\Pattern\PathMode::Trail, false) // => []
104	     *
105	     * @return list<MatchState> The attempts that crossed it
106	     *
107	     * @throws GqlException If a requirement written in the pattern cannot be worked out
108	     */
109	    public function crossOnce(EdgePattern $pattern, MatchState $state, PathMode $mode, bool $repeating): array
110	    {
111	        $standing = $state->current;
112	        if ($standing === null) {
113	            return [];
114	        }
115	
116	        $reached = [];
117	        foreach (EdgeTraversal::from($this->graph, $standing->id, $pattern->direction) as $crossing) {
118	            $arrived = $this->arrival($pattern, $state, $mode, $crossing, $repeating);
119	            if ($arrived !== null) {
120	                $reached[] = $arrived;
121	            }
122	        }
123	
124	        return $reached;
125	    }
126	
127	    /**
128	     * Returns the attempt having crossed one relation, or nothing when it may not.
129	     *
130	     * @param EdgePattern   $pattern   What the pattern requires of the relation
131	     * @param MatchState    $state     How far the attempt has got
132	     * @param PathMode      $mode      What the path may visit more than once
133	     * @param EdgeTraversal $crossing  The relation and where it leads
134	     * @param bool          $repeating Whether the name binds to the chain rather than to this relation
135	     *
136	     * @example A relation leading nowhere the graph knows about is not crossed
137	     *     $edge = new \App\Gql\Datum\EdgeDatum('e', [], [], 'a', 'b');
138	     *     $matching = new \App\Gql\Matching\EdgeMatching(new \App\Gql\Element\ElementGraph([], [], []), new \App\Gql\Evaluation\ExpressionEvaluation(), 10);
139	     *     $state = \App\Gql\Matching\MatchState::before(\App\Gql\Binding\BindingRow::unit())->startingAt(new \App\Gql\Datum\NodeDatum('a'));
140	     *     $pattern = new \App\Gql\Syntax\Pattern\EdgePattern(\App\Gql\Syntax\Pattern\EdgeDirection::Along);
141	     *     $matching->arrival($pattern, $state, \App\Gql\Syntax\Pattern\PathMode::Trail, new \App\Gql\Matching\EdgeTraversal($edge, 'b'), false) // => null
142	     *
143	     * @return null|MatchState The attempt, or null when this relation is not one the pattern crosses
144	     *
145	     * @throws GqlException If a requirement written in the pattern cannot be worked out
146	     */
147	    public function arrival(EdgePattern $pattern, MatchState $state, PathMode $mode, EdgeTraversal $crossing, bool $repeating): ?MatchState
148	    {
149	        $edge = $crossing->edge;
150	        $other = $this->graph->node($crossing->other);
151	        if ($other === null
152	            || !PathModeRule::allowsEdge($mode, $state, $edge)
153	            || !PathModeRule::allowsNode($mode, $state, $other)
154	            || !LabelMatching::satisfies($pattern->labels, $edge->labels)
155	            || (!$repeating && !ElementMatching::agrees($pattern->variable, $edge, $state->row))
156	            || !ElementMatching::satisfies($edge, $pattern->variable, $pattern->filter, $state->row, $this->evaluation)
157	        ) {
158	            return null;
159	        }
160	
161	        $arrived = $state->across($edge, $other);
162	        if ($pattern->variable === null) {
163	            return $arrived;
164	        }
165	
166	        return $arrived->bind(
167	            $pattern->variable,
168	            $repeating ? self::extended($state->row->value($pattern->variable), $edge) : $edge,
169	        );
170	    }
171	
172	    /**
173	     * Returns a chain of relations with one more relation on the end of it.
174	     *
175	     * @param Datum     $crossed The relations crossed so far
176	     * @param EdgeDatum $edge    The one just crossed
177	     *
178	     * @example A chain grows by one relation at a time
179	     *     $chain = new \App\Gql\Datum\ListDatum([new \App\Gql\Datum\EdgeDatum('e', [], [], 'a', 'b')]);
180	     *     count(\App\Gql\Matching\EdgeMatching::extended($chain, new \App\Gql\Datum\EdgeDatum('f', [], [], 'b', 'c'))->items) // => 2
181	     *
182	     * @return ListDatum The longer chain
183	     */
184	    public static function extended(Datum $crossed, EdgeDatum $edge): ListDatum
185	    {
186	        $items = $crossed instanceof ListDatum ? $crossed->items : [];
187	
188	        return new ListDatum([...$items, $edge]);
189	    }
190	}
