195	namespace App\Gql\Matching;
196	
197	use App\Gql\Datum\EdgeDatum;
198	use App\Gql\Element\ElementGraph;
199	use App\Gql\Syntax\Pattern\EdgeDirection;
200	
201	/**
202	 * The relations a pattern can cross from where it is standing.
203	 *
204	 * Which relations those are depends entirely on which way the pattern was drawn, and
205	 * that is the difference between the two questions impact analysis asks. Standing at
206	 * a method, `-[:methodCall]->` leads to what it calls and `<-[:methodCall]-` leads to
207	 * what calls it; the same relations, read from opposite ends.
208	 *
209	 * A pattern drawn without a direction crosses both, which means a relation whose two
210	 * ends are the same symbol is crossed twice — once each way. That is GQL's rule, and
211	 * on a graph of code it is the honest one: a method that calls itself is involved in
212	 * that call as caller and as called.
213	 *
214	 * @visibility App\Gql
215	 */
216	final class EdgeTraversal
217	{
218	    /**
219	     * @param EdgeDatum $edge  The relation that can be crossed
220	     * @param string    $other What identifies the symbol at the other end of it
221	     */
222	    public function __construct(
223	        public readonly EdgeDatum $edge,
224	        public readonly string $other,
225	    ) {}
226	
227	    /**
228	     * Returns the relations a pattern can cross from a symbol.
229	     *
230	     * @param ElementGraph  $graph     The graph being matched against
231	     * @param string        $from      What identifies the symbol being stood at
232	     * @param EdgeDirection $direction Which way the pattern crosses a relation
233	     *
234	     * @example A pattern drawn forwards crosses the relations that leave
235	     *     $edge = new \App\Gql\Datum\EdgeDatum('e', [], [], 'a', 'b');
236	     *     $graph = new \App\Gql\Element\ElementGraph([], ['a' => [$edge]], ['b' => [$edge]]);
237	     *     \App\Gql\Matching\EdgeTraversal::from($graph, 'a', \App\Gql\Syntax\Pattern\EdgeDirection::Along)[0]->other // => 'b'
238	     * @example A pattern drawn backwards crosses the relations that arrive
239	     *     $edge = new \App\Gql\Datum\EdgeDatum('e', [], [], 'a', 'b');
240	     *     $graph = new \App\Gql\Element\ElementGraph([], ['a' => [$edge]], ['b' => [$edge]]);
241	     *     \App\Gql\Matching\EdgeTraversal::from($graph, 'b', \App\Gql\Syntax\Pattern\EdgeDirection::Against)[0]->other // => 'a'
242	     *
243	     * @return list<self> The relations, with the symbol each one leads to
244	     */
245	    public static function from(ElementGraph $graph, string $from, EdgeDirection $direction): array
246	    {
247	        $crossings = [];
248	        if ($direction === EdgeDirection::Along || $direction === EdgeDirection::Either) {
249	            foreach ($graph->leaving($from) as $edge) {
250	                $crossings[] = new self($edge, $edge->target);
251	            }
252	        }
253	        if ($direction === EdgeDirection::Against || $direction === EdgeDirection::Either) {
254	            foreach ($graph->arriving($from) as $edge) {
255	                $crossings[] = new self($edge, $edge->origin);
256	            }
257	        }
258	
259	        return $crossings;
260	    }
261	}
