266	namespace App\Gql\Matching;
267	
268	use App\Gql\Binding\BindingRow;
269	use App\Gql\Datum\Datum;
270	use App\Gql\Datum\DatumOrder;
271	use App\Gql\Datum\EdgeDatum;
272	use App\Gql\Datum\NodeDatum;
273	use App\Gql\Evaluation\ExpressionEvaluation;
274	use App\Gql\Evaluation\Logic;
275	use App\Gql\GqlException;
276	use App\Gql\Syntax\Pattern\ElementFilter;
277	
278	/**
279	 * Whether one element is what a pattern asked for.
280	 *
281	 * Three things have to hold, and the order they are asked in is the order they get
282	 * cheaper to be wrong about. The labels first, because they rule out most of a graph
283	 * for nothing; then the properties written as equalities, which are a lookup each;
284	 * then the predicate, which is the only one that has to evaluate an expression.
285	 *
286	 * The predicate sees the element bound to its own variable, which is what makes
287	 * `(p:Method WHERE p.visibility = 'public')` mean what it looks like. For an edge
288	 * crossed by a repeating pattern the variable is bound to the one edge being
289	 * considered rather than to the list of all of them, which is GQL's rule and the
290	 * reason a repeating pattern can be narrowed edge by edge.
291	 *
292	 * @visibility App\Gql
293	 */
294	final class ElementMatching
295	{
296	    /**
297	     * Reports whether a symbol satisfies what a pattern requires of it.
298	     *
299	     * @param NodeDatum            $node       The symbol
300	     * @param null|string          $variable   The name the pattern binds it to, if any
301	     * @param ElementFilter        $filter     What the pattern requires beyond its labels
302	     * @param BindingRow           $row        What is already bound
303	     * @param ExpressionEvaluation $evaluation How a predicate is worked out
304	     *
305	     * @example A symbol with the property a pattern asked for satisfies it
306	     *     $node = new \App\Gql\Datum\NodeDatum('a', [], ['kind' => new \App\Gql\Datum\StringDatum('method')]);
307	     *     $parser = new \App\Gql\Parsing\ExpressionParser(\App\Gql\Parsing\TokenReader::of("'method'"));
308	     *     $filter = new \App\Gql\Syntax\Pattern\ElementFilter(['kind' => $parser->parse()]);
309	     *     \App\Gql\Matching\ElementMatching::satisfies($node, null, $filter, \App\Gql\Binding\BindingRow::unit(), new \App\Gql\Evaluation\ExpressionEvaluation()) // => true
310	     *
311	     * @return bool True when it does
312	     *
313	     * @throws GqlException If a requirement cannot be worked out
314	     */
315	    public static function satisfies(
316	        EdgeDatum|NodeDatum $node,
317	        ?string $variable,
318	        ElementFilter $filter,
319	        BindingRow $row,
320	        ExpressionEvaluation $evaluation,
321	    ): bool {
322	        if ($filter->empty()) {
323	            return true;
324	        }
325	
326	        $scope = $variable === null ? $row : $row->with($variable, $node);
327	        foreach ($filter->properties as $name => $expected) {
328	            if (DatumOrder::equals($node->property($name), $evaluation->evaluate($expected, $scope)) !== true) {
329	                return false;
330	            }
331	        }
332	        if ($filter->predicate === null) {
333	            return true;
334	        }
335	
336	        return Logic::holds($evaluation->evaluate($filter->predicate, $scope));
337	    }
338	
339	    /**
340	     * Reports whether an element agrees with what a name is already bound to.
341	     *
342	     * Writing the same name twice in one pattern says the two places must be the same
343	     * element, which is how a query asks for two methods of the same class or two
344	     * controllers that reach the same repository. It is also how a pattern joins to
345	     * what an earlier clause found.
346	     *
347	     * @param null|string $variable The name the pattern binds, if any
348	     * @param Datum       $element  The element being considered
349	     * @param BindingRow  $row      What is already bound
350	     *
351	     * @example A name nothing bound agrees with anything
352	     *     \App\Gql\Matching\ElementMatching::agrees('p', new \App\Gql\Datum\NodeDatum('a'), \App\Gql\Binding\BindingRow::unit()) // => true
353	     * @example A name bound elsewhere agrees only with the same element
354	     *     $row = \App\Gql\Binding\BindingRow::unit()->with('p', new \App\Gql\Datum\NodeDatum('a'));
355	     *     \App\Gql\Matching\ElementMatching::agrees('p', new \App\Gql\Datum\NodeDatum('b'), $row) // => false
356	     *
357	     * @return bool True when it agrees
358	     *
359	     * @throws GqlException If the name is bound to a value that cannot be compared with an element
360	     */
361	    public static function agrees(?string $variable, Datum $element, BindingRow $row): bool
362	    {
363	        if ($variable === null || !$row->has($variable)) {
364	            return true;
365	        }
366	
367	        return DatumOrder::equals($row->value($variable), $element) === true;
368	    }
369	}
