376	use App\Gql\Syntax\Pattern\LabelOperator;
377	use App\Gql\Syntax\Pattern\LabelPattern;
378	
379	/**
380	 * Whether the labels an element carries satisfy what a pattern requires of them.
381	 *
382	 * Matching is covariant, which is GQL's word for the thing that makes labels useful:
383	 * an element that carries more labels than the pattern names still matches. A pattern
384	 * asking for `Callable` matches a method, which carries `Method` and `Member` as well,
385	 * and a pattern asking for nothing matches everything.
386	 *
387	 * @visibility App\Gql
388	 */
389	final class LabelMatching
390	{
391	    /**
392	     * Reports whether a set of labels satisfies a requirement.
393	     *
394	     * @param null|LabelPattern $required What the pattern requires, or null when it requires nothing
395	     * @param list<string>      $labels   The labels the element carries
396	     *
397	     * @example A pattern that requires nothing is satisfied by anything
398	     *     \App\Gql\Matching\LabelMatching::satisfies(null, []) // => true
399	     * @example A label the element carries satisfies a requirement for it
400	     *     \App\Gql\Matching\LabelMatching::satisfies(\App\Gql\Syntax\Pattern\LabelPattern::named('Method'), ['Method', 'Callable']) // => true
401	     * @example A refusal is satisfied by an element that does not carry the label
402	     *     $required = \App\Gql\Syntax\Pattern\LabelPattern::neither(\App\Gql\Syntax\Pattern\LabelPattern::named('Interface'));
403	     *     \App\Gql\Matching\LabelMatching::satisfies($required, ['Class', 'ClassLike']) // => true
404	     *
405	     * @return bool True when the labels satisfy it
406	     */
407	    public static function satisfies(?LabelPattern $required, array $labels): bool
408	    {
409	        if ($required === null) {
410	            return true;
411	        }
412	
413	        return match ($required->operator) {
414	            LabelOperator::Anything => $labels !== [],
415	            LabelOperator::Named => in_array($required->name, $labels, true),
416	            LabelOperator::Both => self::satisfies($required->operands[0] ?? null, $labels)
417	                && self::satisfies($required->operands[1] ?? null, $labels),
418	            LabelOperator::Either => self::satisfies($required->operands[0] ?? null, $labels)
419	                || self::satisfies($required->operands[1] ?? null, $labels),
420	            LabelOperator::Neither => !self::satisfies($required->operands[0] ?? null, $labels),
421	        };
422	    }
423	}
