428	namespace App\Gql\Matching;
429	
430	use App\Gql\Binding\BindingRow;
431	use App\Gql\Datum\Datum;
432	use App\Gql\Datum\EdgeDatum;
433	use App\Gql\Datum\NodeDatum;
434	use App\Gql\Datum\PathDatum;
435	
436	/**
437	 * How far one attempt at matching a pattern has got.
438	 *
439	 * Matching a graph pattern is a search, and a search needs to remember four things at
440	 * once: what it has bound so far, where in the graph it is standing, the path it took
441	 * to get there, and what it has already been through. The last two are not the same:
442	 * the path is the answer a query can ask for, and what has been been through is what
443	 * keeps the search finite.
444	 *
445	 * Every step produces a new state rather than changing this one, because a search
446	 * that finds three ways forward has to carry on down all three from the same place.
447	 *
448	 * @visibility App\Gql
449	 */
450	final class MatchState
451	{
452	    /**
453	     * @param BindingRow          $row     What the attempt has bound so far
454	     * @param null|NodeDatum      $current Where in the graph it is standing, or null before it has started
455	     * @param null|PathDatum      $path    The path it took to get there, or null before it has started
456	     * @param array<string, true> $edges   The relations it has crossed, by what identifies them
457	     * @param array<string, true> $nodes   The symbols it has met, by what identifies them
458	     * @param null|string         $start   What identifies the symbol it started from, or null before it has started
459	     */
460	    public function __construct(
461	        public readonly BindingRow $row,
462	        public readonly ?NodeDatum $current = null,
463	        public readonly ?PathDatum $path = null,
464	        private readonly array $edges = [],
465	        private readonly array $nodes = [],
466	        private readonly ?string $start = null,
467	    ) {}
468	
469	    /**
470	     * Returns the attempt as it stands before it has gone anywhere.
471	     *
472	     * @param BindingRow $row What is already bound when the pattern is reached
473	     *
474	     * @example An attempt that has not started stands nowhere
475	     *     \App\Gql\Matching\MatchState::before(\App\Gql\Binding\BindingRow::unit())->current // => null
476	     *
477	     * @return self The attempt
478	     */
479	    public static function before(BindingRow $row): self
480	    {
481	        return new self($row);
482	    }
483	
484	    /**
485	     * Returns the attempt standing at a symbol it has just started from.
486	     *
487	     * @param NodeDatum $node The symbol
488	     *
489	     * @example Starting somewhere begins a path there
490	     *     $started = \App\Gql\Matching\MatchState::before(\App\Gql\Binding\BindingRow::unit())->startingAt(new \App\Gql\Datum\NodeDatum('a'));
491	     *     $started->path?->length() // => 0
492	     *
493	     * @return self The attempt, standing there
494	     */
495	    public function startingAt(NodeDatum $node): self
496	    {
497	        return new self($this->row, $node, PathDatum::at($node), $this->edges, [$node->id => true], $node->id);
498	    }
499	
500	    /**
501	     * Returns the attempt having crossed a relation to another symbol.
502	     *
503	     * @param EdgeDatum $edge The relation crossed
504	     * @param NodeDatum $node The symbol arrived at
505	     *
506	     * @example Crossing a relation makes the path one longer
507	     *     $started = \App\Gql\Matching\MatchState::before(\App\Gql\Binding\BindingRow::unit())->startingAt(new \App\Gql\Datum\NodeDatum('a'));
508	     *     $crossed = $started->across(new \App\Gql\Datum\EdgeDatum('e', [], [], 'a', 'b'), new \App\Gql\Datum\NodeDatum('b'));
509	     *     $crossed->path?->length() // => 1
510	     *
511	     * @return self The attempt, standing at the other symbol
512	     */
513	    public function across(EdgeDatum $edge, NodeDatum $node): self
514	    {
515	        $path = $this->path ?? PathDatum::at($node);
516	
517	        return new self(
518	            $this->row,
519	            $node,
520	            $this->path === null ? $path : $path->continuedBy($edge, $node),
521	            [...$this->edges, $edge->id => true],
522	            [...$this->nodes, $node->id => true],
523	            $this->start ?? $node->id,
524	        );
525	    }
526	
527	    /**
528	     * Returns the attempt with one more name bound.
529	     *
530	     * @param string $name  The name
531	     * @param Datum  $value What to bind it to
532	     *
533	     * @example Binding a name leaves everything else about the attempt alone
534	     *     $before = \App\Gql\Matching\MatchState::before(\App\Gql\Binding\BindingRow::unit());
535	     *     $before->bind('n', new \App\Gql\Datum\IntegerDatum(1))->current // => null
536	     *
537	     * @return self The attempt, with that binding
538	     */
539	    public function bind(string $name, Datum $value): self
540	    {
