1083	     *     $edge = new \App\Gql\Syntax\Pattern\EdgePattern(\App\Gql\Syntax\Pattern\EdgeDirection::Along, 'e');
1084	     *     $terms = [new \App\Gql\Syntax\Pattern\NodePattern('a'), $edge, new \App\Gql\Syntax\Pattern\NodePattern('b')];
