1094	            foreach (self::repeatedIn($path->terms) as $name) {
1095	                $names[$name] = true;
1096	            }
1097	        }
1098	
1099	        return array_keys($names);
1100	    }
1101	
1102	    /**
1103	     * Returns the names the pieces of a path bind to a group list.
1104	     *
1105	     * @param list<PathTerm> $terms The pieces of the path
1106	     *
1107	     * @example A parenthesised stretch of pattern is searched for them too
1108	     *     $edge = new \App\Gql\Syntax\Pattern\EdgePattern(\App\Gql\Syntax\Pattern\EdgeDirection::Along, 'e', null, new \App\Gql\Syntax\Pattern\ElementFilter(), new \App\Gql\Syntax\Pattern\Quantifier(1, 3));
