1110	     *
1111	     * @return list<string> The names, in the order they are written
1112	     */
1113	    public static function repeatedIn(array $terms): array
1114	    {
1115	        $names = [];
1116	        foreach ($terms as $term) {
1117	            if ($term instanceof GroupPattern) {
1118	                array_push($names, ...self::repeatedIn($term->terms));
1119	
1120	                continue;
1121	            }
1122	            if ($term instanceof EdgePattern && $term->variable !== null && $term->quantifier !== null) {
1123	                $names[] = $term->variable;
1124	            }
1125	        }
1126	
1127	        return $names;
1128	    }
1129	
1130	    /**
1131	     * Returns every name the pieces of a path would bind.
1132	     *
1133	     * @param list<PathTerm> $terms The pieces of the path
1134	     *
1135	     * @example A parenthesised stretch of pattern binds the names inside it
1136	     *     $group = new \App\Gql\Syntax\Pattern\GroupPattern([new \App\Gql\Syntax\Pattern\NodePattern('a')]);
1137	     *     \App\Gql\Matching\PatternVariables::inTerms([$group]) // => ['a']
1138	     *
1139	     * @return list<string> The names, in the order they are written
1140	     */
1141	    public static function inTerms(array $terms): array
1142	    {
1143	        $names = [];
1144	        foreach ($terms as $term) {
1145	            if ($term instanceof GroupPattern) {
1146	                array_push($names, ...self::inTerms($term->terms));
1147	
1148	                continue;
1149	            }
1150	            $variable = $term instanceof NodePattern || $term instanceof EdgePattern ? $term->variable : null;
1151	            if ($variable !== null) {
1152	                $names[] = $variable;
1153	            }
1154	        }
1155	
1156	        return $names;
1157	    }
