23	/**
24	 * Running one straight run of clauses, from one row in to a result out.
25	 *
26	 * The run starts from a single row binding nothing, which is what makes the first
27	 * clause run exactly once, and each clause afterwards is handed what the last one
28	 * produced. Nothing here knows which clause came before it, which is the property
29	 * that makes a long query readable in the order it is written.
30	 *
31	 * Every run ends in a `RETURN`, because GQL's linear query does: the reader who writes
32	 * `MATCH (p:Method WHERE p.deprecated)` and stops there is asking a question the
33	 * language has no way to answer, and `RETURN *` is how the language writes it.
34	 *
35	 * @visibility App\Gql
36	 */
37	final class BlockExecution
38	{
39	    /**
40	     * Running the clause that looks for a shape in the graph.
41	     */
42	    private readonly MatchExecution $matches;
43	
44	    /**
45	     * Running the clauses that work on rows without touching the graph.
46	     */
47	    private readonly RowExecution $rows;
48	
49	    /**
50	     * Running the clause that decides what the reader is shown.
51	     */
52	    private readonly ReturnExecution $projection;
53	
54	    /**
55	     * @param ElementGraph $graph    The graph being queried
56	     */
57	    public function __construct(
58	        ElementGraph $graph,
59	    ) {
60	        $evaluation = new ExpressionEvaluation();
61	        $this->matches = new MatchExecution($graph, $evaluation);
62	        $this->rows = new RowExecution($evaluation);
63	        $this->projection = new ReturnExecution($this->rows);
64	    }
65	
66	    /**
67	     * Runs a straight run of clauses and returns what it answered.
68	     *
69	     * @param QueryBlock $block The clauses
70	     *
71	     * @example A run that says what to show is shown that
72	     *     $block = \App\Gql\Parsing\Parser::read('RETURN 1 AS n')->blocks[0];
73	     *     $execution = new \App\Gql\Execution\BlockExecution(new \App\Gql\Element\ElementGraph([], [], []));
74	     *     $execution->run($block)->rows[0]->value(0)->toText() // => '1'
75	     * @example A run that shows everything it bound is shown all of it
76	     *     $block = \App\Gql\Parsing\Parser::read('LET n = 1 RETURN *')->blocks[0];
77	     *     $execution = new \App\Gql\Execution\BlockExecution(new \App\Gql\Element\ElementGraph([], [], []));
78	     *     $execution->run($block)->headings() // => ['n']
79	     *
80	     * @return ResultTable What it answered
81	     *
82	     * @throws GqlException If a clause cannot be run
83	     */
84	    public function run(QueryBlock $block): ResultTable
85	    {
86	        $table = BindingTable::unit();
87	        $headings = null;
88	        $groupLists = [];
89	        foreach ($block->clauses as $clause) {
90	            if ($clause instanceof MatchClause) {
91	                array_push($groupLists, ...PatternVariables::groupLists($clause->pattern));
92	            }
93	            if ($clause instanceof ReturnClause) {
94	                $headings = $this->projection->headings($clause, $table);
95	                $table = $this->projection->run($clause, $table, $groupLists);
96	
97	                continue;
98	            }
99	            $table = $this->apply($clause, $table);
100	        }
101	
102	        return ResultTable::of($headings ?? $table->names(), $table);
103	    }
104	
105	    /**
106	     * Returns the rows one clause produces from the rows it is given.
107	     *
108	     * @param Clause       $clause The clause
109	     * @param BindingTable $table  The rows it is given
110	     *
111	     * @example A clause that keeps a stretch of the rows keeps that stretch
112	     *     $execution = new \App\Gql\Execution\BlockExecution(new \App\Gql\Element\ElementGraph([], [], []));
113	     *     $execution->apply(new \App\Gql\Syntax\Clause\PageClause(0, 0), \App\Gql\Binding\BindingTable::unit())->rows // => []
114	     *
115	     * @return BindingTable The rows it produces
116	     *
117	     * @throws GqlException If the clause is not one peq knows how to run
118	     */
119	    public function apply(Clause $clause, BindingTable $table): BindingTable
120	    {
121	        if ($clause instanceof MatchClause) {
122	            return $this->matches->run($clause, $table);
123	        }
124	        if ($clause instanceof LetClause) {
125	            return $this->rows->bind($clause, $table);
126	        }
127	        if ($clause instanceof FilterClause) {
128	            return $this->rows->keep($clause, $table);
129	        }
130	        if ($clause instanceof OrderByClause) {
131	            return $this->rows->order($clause, $table);
132	        }
133	        if ($clause instanceof PageClause) {
134	            return $this->rows->page($clause, $table);
135	        }
136	
137	        throw GqlException::because(StatusCode::UnknownFeature, 'this clause is not one peq knows how to run');
138	    }
139	}
