158	/**
159	 * Running a MATCH: finding a shape, and joining it to what is already known.
160	 *
161	 * Every row that comes in is matched separately and contributes as many rows as the
162	 * graph matches it, which is what makes a chain of matches a join: the names a
163	 * pattern shares with the rows it is given are already bound, so the search starts
164	 * from them rather than from the whole graph.
165	 *
166	 * An optional match keeps the rows that matched nothing, exactly as they were. That
167	 * is what a left outer join is, and it is the only way to ask "and what, if anything,
168	 * does each of these reach" without silently dropping the ones that reach nothing —
169	 * which, in impact analysis, are often the interesting ones.
170	 *
171	 * @visibility App\Gql
172	 */
173	final class MatchExecution
174	{
175	    /**
176	     * Finding every way a pattern matches.
177	     */
178	    private readonly PatternMatching $patterns;
179	
180	    /**
181	     * @param ElementGraph         $graph      The graph being queried
182	     * @param ExpressionEvaluation $evaluation How a predicate is worked out
183	     */
184	    public function __construct(
185	        ElementGraph $graph,
186	        private readonly ExpressionEvaluation $evaluation,
187	    ) {
188	        $this->patterns = new PatternMatching($graph, $evaluation);
189	    }
190	
191	    /**
192	     * Returns the rows a MATCH produces from the rows it is given.
193	     *
194	     * @param MatchClause  $clause The clause
195	     * @param BindingTable $table  The rows it is given
196	     *
197	     * @example A pattern over a graph with no symbols produces no rows
198	     *     $execution = new \App\Gql\Execution\MatchExecution(new \App\Gql\Element\ElementGraph([], [], []), new \App\Gql\Evaluation\ExpressionEvaluation());
199	     *     $pattern = new \App\Gql\Syntax\Pattern\GraphPattern([new \App\Gql\Syntax\Pattern\PathPattern([new \App\Gql\Syntax\Pattern\NodePattern('p')])]);
200	     *     $execution->run(new \App\Gql\Syntax\Clause\MatchClause($pattern), \App\Gql\Binding\BindingTable::unit())->rows // => []
201	     * @example An optional pattern that matches nothing keeps the row it was given
202	     *     $execution = new \App\Gql\Execution\MatchExecution(new \App\Gql\Element\ElementGraph([], [], []), new \App\Gql\Evaluation\ExpressionEvaluation());
203	     *     $pattern = new \App\Gql\Syntax\Pattern\GraphPattern([new \App\Gql\Syntax\Pattern\PathPattern([new \App\Gql\Syntax\Pattern\NodePattern('p')])]);
204	     *     count($execution->run(new \App\Gql\Syntax\Clause\MatchClause($pattern, null, true), \App\Gql\Binding\BindingTable::unit())->rows) // => 1
205	     *
206	     * @return BindingTable The rows it produces
207	     *
208	     * @throws GqlException If a requirement written in the pattern cannot be worked out
209	     */
210	    public function run(MatchClause $clause, BindingTable $table): BindingTable
211	    {
212	        $produced = [];
213	        foreach ($table->rows as $row) {
214	            $matched = $this->kept($clause, $row);
215	            if ($matched === [] && $clause->optional) {
216	                $produced[] = $row->withAll(self::absent($clause, $row));
217	
218	                continue;
219	            }
220	            array_push($produced, ...$matched);
221	        }
222	
223	        return new BindingTable($produced);
224	    }
225	
226	    /**
227	     * Returns the names a pattern would have bound, bound to nothing.
228	     *
229	     * A row an optional pattern did not match keeps every name the pattern would have
230	     * bound, bound to the absence of a value. That is what makes `RETURN parent.name`
231	     * answer with nothing for a class that extends nothing, rather than reporting a
232	     * name the query plainly did bind.
233	     *
234	     * A name the row already carries is left alone. An optional pattern usually
235	     * continues from something an earlier clause found — `(c)-[:extends]->(parent)` —
236	     * and forgetting what `c` was because the pattern found no parent would throw away
237	     * the row the query was asking about.
238	     *
239	     * @param MatchClause $clause The clause
240	     * @param BindingRow  $row    The row the pattern did not match
241	     *
242	     * @example A pattern that binds nothing has nothing to leave absent
243	     *     $pattern = new \App\Gql\Syntax\Pattern\GraphPattern([new \App\Gql\Syntax\Pattern\PathPattern([new \App\Gql\Syntax\Pattern\NodePattern()])]);
244	     *     \App\Gql\Execution\MatchExecution::absent(new \App\Gql\Syntax\Clause\MatchClause($pattern, null, true), \App\Gql\Binding\BindingRow::unit()) // => []
245	     * @example A name the row already carries is left as it was
246	     *     $pattern = new \App\Gql\Syntax\Pattern\GraphPattern([new \App\Gql\Syntax\Pattern\PathPattern([new \App\Gql\Syntax\Pattern\NodePattern('c')])]);
247	     *     $row = \App\Gql\Binding\BindingRow::unit()->with('c', new \App\Gql\Datum\IntegerDatum(1));
248	     *     \App\Gql\Execution\MatchExecution::absent(new \App\Gql\Syntax\Clause\MatchClause($pattern, null, true), $row) // => []
249	     *
250	     * @return array<string, Datum> The names the pattern would have bound and the row does not carry
251	     */
252	    public static function absent(MatchClause $clause, BindingRow $row): array
253	    {
254	        $bindings = [];
255	        foreach (PatternVariables::of($clause->pattern) as $name) {
256	            if (!$row->has($name)) {
257	                $bindings[$name] = new NullDatum();
258	            }
259	        }
260	
261	        return $bindings;
262	    }
263	
264	    /**
265	     * Returns the ways a pattern matched one row, after the clause's own narrowing.
266	     *
267	     * A `WHERE` written after the pattern narrows the matches rather than the search,
268	     * which is the difference between it and a `WHERE` written inside the pattern:
269	     * the one inside stops the search early, and this one sees whole matches.
270	     *
271	     * @param MatchClause $clause The clause
272	     * @param BindingRow  $row    The row being matched from
273	     *
274	     * @example A pattern over a graph with no symbols matches nothing
275	     *     $execution = new \App\Gql\Execution\MatchExecution(new \App\Gql\Element\ElementGraph([], [], []), new \App\Gql\Evaluation\ExpressionEvaluation());
276	     *     $pattern = new \App\Gql\Syntax\Pattern\GraphPattern([new \App\Gql\Syntax\Pattern\PathPattern([new \App\Gql\Syntax\Pattern\NodePattern('p')])]);
277	     *     $execution->kept(new \App\Gql\Syntax\Clause\MatchClause($pattern), \App\Gql\Binding\BindingRow::unit()) // => []
278	     *
279	     * @return list<BindingRow> The matches the clause keeps
280	     *
281	     * @throws GqlException If a requirement written in the pattern cannot be worked out
282	     */
283	    public function kept(MatchClause $clause, BindingRow $row): array
284	    {
285	        $matched = $this->patterns->match($clause->pattern, $row);
286	        if ($clause->where === null) {
287	            return $matched;
288	        }
289	
290	        $kept = [];
291	        foreach ($matched as $candidate) {
292	            if (Logic::holds($this->evaluation->evaluate($clause->where, $candidate))) {
293	                $kept[] = $candidate;
294	            }
295	        }
296	
297	        return $kept;
298	    }
