314	/**
315	 * The largest upper bound a quantifier may be written with.
316	 *
317	 * ISO/IEC 39075 leaves this to the implementation — it is IL018, "the maximum value of
318	 * the upper bound of a general quantifier" — and peq makes it `--hops`. What it limits
319	 * is what a query writes: `{1,20}` asks for up to twenty repetitions, and a walk of
320	 * twenty steps through a graph with cycles can be more work than anyone meant to ask
321	 * for. A quantifier with no upper bound is not affected, because GQL allows one only
322	 * under a restrictor, which is what keeps its matches finite.
323	 *
324	 * The limit is checked before anything runs, so a query that exceeds it is refused
325	 * whatever the graph holds, rather than only when a match happens to reach that far.
326	 *
327	 * @visibility App\Gql
328	 */
329	final class QuantifierLimit
330	{
331	    /**
332	     * Refuses a query that writes an upper bound above the limit.
333	     *
334	     * @param Query $query The query
335	     * @param int   $limit The largest upper bound a quantifier may be written with
336	     *
337	     * @example A query within the limit is left alone
338	     *     \App\Gql\Execution\QuantifierLimit::check(\App\Gql\Parsing\Parser::read('MATCH (a)-[e]->{1,3}(b) RETURN a'), 3) // => null
339	     * @example One beyond it is refused, and told how to raise it
340	     *     \App\Gql\Execution\QuantifierLimit::check(\App\Gql\Parsing\Parser::read('MATCH (a)-[e]->{1,4}(b) RETURN a'), 3) // throws \App\Gql\GqlException: --hops
341	     *
342	     * @throws GqlException If a quantifier is written with an upper bound above the limit
343	     */
344	    public static function check(Query $query, int $limit): void
345	    {
346	        foreach ($query->blocks as $block) {
347	            foreach ($block->clauses as $clause) {
348	                if (!$clause instanceof MatchClause) {
349	                    continue;
350	                }
351	                foreach ($clause->pattern->paths as $path) {
352	                    self::checkTerms($path->terms, $limit);
353	                }
354	            }
355	        }
356	    }
357	
358	    /**
359	     * Refuses the pieces of a path when one of them writes an upper bound above the limit.
360	     *
361	     * @param list<PathTerm> $terms The pieces
362	     * @param int            $limit The largest upper bound a quantifier may be written with
363	     *
364	     * @example A path that repeats nothing is within any limit
365	     *     \App\Gql\Execution\QuantifierLimit::checkTerms([new \App\Gql\Syntax\Pattern\NodePattern()], 0) // => null
366	     *
367	     * @throws GqlException If one of them writes an upper bound above the limit
368	     */
369	    public static function checkTerms(array $terms, int $limit): void
370	    {
371	        foreach ($terms as $term) {
372	            $most = match (true) {
373	                $term instanceof EdgePattern => $term->quantifier?->most,
374	                $term instanceof GroupPattern => $term->quantifier?->most,
375	                default => null,
376	            };
377	            if ($most !== null && $most > $limit) {
378	                throw GqlException::because(
379	                    StatusCode::SyntaxError,
380	                    sprintf('a quantifier may repeat at most %d times here, and one is written to repeat up to %d: raise --hops to allow more', $limit, $most),
381	                );
382	            }
383	            if ($term instanceof GroupPattern) {
384	                self::checkTerms($term->terms, $limit);
385	            }
386	        }
387	    }
388	}
