403	/**
404	 * Running a whole query against an analysed dependency graph.
405	 *
406	 * This is the boundary between peq and its query language: everything on the far side
407	 * of it is GQL, and everything on this side is a graph of PHP symbols. A caller hands
408	 * over a graph and a query and is handed a result and a status; nothing about parsing,
409	 * matching or three-valued logic reaches past here.
410	 *
411	 * Each run of clauses is executed independently and the results are combined
412	 * afterwards, because nothing flows across a set operator — a name bound on the left
413	 * of a `UNION` means nothing on its right.
414	 */
415	final class QueryExecution
416	{
417	    /**
418	     * @param ElementGraph $graph    The graph being queried
419	     * @param int          $hopLimit The largest upper bound a quantifier may be written with, which is IL018
420	     */
421	    public function __construct(
422	        private readonly ElementGraph $graph,
423	        private readonly int $hopLimit = 10,
424	    ) {}
425	
426	    /**
427	     * Prepares to query an analysed dependency graph.
428	     *
429	     * @param Graph $graph    The graph analysis produced
430	     * @param int   $hopLimit The largest upper bound a quantifier may be written with, which is IL018
431	     *
432	     * @example A graph analysis produced can be queried as it stands
433	     *     \App\Gql\Execution\QueryExecution::against(new \App\Analyzer\Graph\Graph())->query('RETURN 1 AS n')->rows[0]->value(0)->toText() // => '1'
434	     *
435	     * @return self The execution
436	     */
437	    public static function against(Graph $graph, int $hopLimit = 10): self
438	    {
439	        return new self(GraphProjection::of($graph), $hopLimit);
440	    }
441	
442	    /**
443	     * Reads a query and runs it.
444	     *
445	     * @param string $source The query, as it was written
446	     *
447	     * @example A query that finds nothing says so rather than failing
448	     *     $found = \App\Gql\Execution\QueryExecution::against(new \App\Analyzer\Graph\Graph())->query('MATCH (p:Method) RETURN p');
449	     *     $found->status() // => \App\Gql\StatusCode::NoData
450	     *
451	     * @return ResultTable What it answered
452	     *
453	     * @throws GqlException If the query cannot be read or cannot be run
454	     */
455	    public function query(string $source): ResultTable
456	    {
457	        return $this->run(Parser::read($source));
458	    }
