460	    /**
461	     * Runs a query that has already been read.
462	     *
463	     * @param Query $query The query
464	     *
465	     * @example A query that combines two runs answers with both
466	     *     $parsed = \App\Gql\Parsing\Parser::read('RETURN 1 AS n UNION ALL RETURN 2 AS n');
467	     *     count(\App\Gql\Execution\QueryExecution::against(new \App\Analyzer\Graph\Graph())->run($parsed)->rows) // => 2
468	     *
469	     * @return ResultTable What it answered
470	     *
471	     * @throws GqlException If the query cannot be run
472	     */
473	    public function run(Query $query): ResultTable
474	    {
475	        QuantifierLimit::check($query, $this->hopLimit);
476	        $blocks = new BlockExecution($this->graph);
477	        $answered = $blocks->run($query->blocks[0]);
478	
479	        foreach ($query->operators as $place => $operator) {
480	            $answered = SetOperation::combine($operator, $answered, $blocks->run($query->blocks[$place + 1]));
481	        }
482	
483	        return $answered;
484	    }
