503	/**
504	 * Running a RETURN: deciding what the reader is shown.
505	 *
506	 * The one real decision here is whether the projection summarises its rows or reports
507	 * them, and it is made from the shape of the expressions rather than from the data:
508	 * a projection holding a summary anywhere inside it produces one row per group, and
509	 * one holding none produces one row per row. Grouping without a `GROUP BY` makes a
510	 * single group of everything, which is why `RETURN count(*)` answers once.
511	 *
512	 * Projected columns are added to the row they came from rather than replacing it.
513	 * That is what lets an ordering written after the projection sort by something the
514	 * projection did not show — `RETURN a, b ORDER BY r.creationDate` — which GQL allows
515	 * and a reader reaches for more often than it sounds.
516	 *
517	 * @visibility App\Gql
518	 */
519	final class ReturnExecution
520	{
521	    /**
522	     * @param RowExecution $rows How rows are ordered and paged
523	     */
524	    public function __construct(
525	        private readonly RowExecution $rows,
526	    ) {}
527	
528	    /**
529	     * Returns what the columns of the result are called.
530	     *
531	     * A projection that asks for everything is headed by the names that are in scope
532	     * where it is written, which is decided when the query runs rather than when it
533	     * is read.
534	     *
535	     * @param ReturnClause $clause The clause
536	     * @param BindingTable $table  The rows it is given
537	     *
538	     * @example A projection that asks for everything shows what is bound
539	     *     $row = \App\Gql\Binding\BindingRow::unit()->with('p', new \App\Gql\Datum\NullDatum());
540	     *     $execution = new \App\Gql\Execution\ReturnExecution(new \App\Gql\Execution\RowExecution(new \App\Gql\Evaluation\ExpressionEvaluation()));
541	     *     $execution->headings(new \App\Gql\Syntax\Clause\ReturnClause(), new \App\Gql\Binding\BindingTable([$row])) // => ['p']
542	     *
543	     * @return list<string> The headings, in the order they are shown
544	     */
545	    public function headings(ReturnClause $clause, BindingTable $table): array
546	    {
547	        if ($clause->everything()) {
548	            return $table->names();
549	        }
550	
551	        return array_map(static fn (Projection $column): string => $column->heading(), $clause->columns);
552	    }
553	
554	    /**
555	     * Returns the rows a RETURN produces.
556	     *
557	     * @param ReturnClause $clause     The clause
558	     * @param BindingTable $table      The rows it is given
559	     * @param list<string> $groupLists The names a repeating pattern bound to every relation it crossed
560	     *
561	     * @example A projection that summarises answers once, even over no rows at all
562	     *     $counted = new \App\Gql\Syntax\Expression\CallExpression('count', [], false, true);
563	     *     $clause = new \App\Gql\Syntax\Clause\ReturnClause([new \App\Gql\Syntax\Clause\Projection($counted, 'n', 'count(*)')]);
564	     *     $execution = new \App\Gql\Execution\ReturnExecution(new \App\Gql\Execution\RowExecution(new \App\Gql\Evaluation\ExpressionEvaluation()));
565	     *     $execution->run($clause, \App\Gql\Binding\BindingTable::nothing())->rows[0]->value('n')->toText() // => '0'
566	     *
567	     * @return BindingTable The rows it produces
568	     *
569	     * @throws GqlException If a column cannot be worked out
570	     */
571	    public function run(ReturnClause $clause, BindingTable $table, array $groupLists = []): BindingTable
572	    {
573	        $produced = $this->summarises($clause, $groupLists)
574	            ? $this->summarised($clause, $table)
575	            : $this->reported($clause, $table);
576	
577	        if ($clause->distinct) {
578	            $produced = self::once($this->headings($clause, $table), $produced);
579	        }
580	        if ($clause->orderBy !== []) {
581	            $produced = $this->rows->sorted($clause->orderBy, $produced);
582	        }
583	        if ($clause->page !== null) {
584	            $produced = array_slice($produced, $clause->page->offset, $clause->page->limit);
585	        }
586	
587	        return new BindingTable($produced);
588	    }
