590	    /**
591	     * Reports whether a projection summarises its rows rather than reporting them.
592	     *
593	     * A summary written over a group list is not one of these. It summarises along the
594	     * row it is written for rather than down the table, which is GQL's rule that
595	     * horizontal aggregation takes precedence, so a projection holding nothing else
596	     * keeps one row per match.
597	     *
598	     * @param ReturnClause $clause     The clause
599	     * @param list<string> $groupLists The names a repeating pattern bound to every relation it crossed
600	     *
601	     * @example A projection that groups summarises
602	     *     $key = new \App\Gql\Syntax\Expression\VariableExpression('kind');
603	     *     $clause = new \App\Gql\Syntax\Clause\ReturnClause([], false, [$key]);
604	     *     $execution = new \App\Gql\Execution\ReturnExecution(new \App\Gql\Execution\RowExecution(new \App\Gql\Evaluation\ExpressionEvaluation()));
605	     *     $execution->summarises($clause) // => true
606	     * @example A projection that shows properties does not
607	     *     $execution = new \App\Gql\Execution\ReturnExecution(new \App\Gql\Execution\RowExecution(new \App\Gql\Evaluation\ExpressionEvaluation()));
608	     *     $execution->summarises(new \App\Gql\Syntax\Clause\ReturnClause()) // => false
609	     *
610	     * @return bool True when it produces one row per group
611	     */
612	    public function summarises(ReturnClause $clause, array $groupLists = []): bool
613	    {
614	        if ($clause->groupBy !== []) {
615	            return true;
616	        }
617	        foreach ($clause->columns as $column) {
618	            if (AggregateDetection::within($column->value, $groupLists)) {
619	                return true;
620	            }
621	        }
622	
623	        return false;
624	    }
