626	    /**
627	     * Returns one row per row, with the projected columns added to it.
628	     *
629	     * @param ReturnClause $clause The clause
630	     * @param BindingTable $table  The rows it is given
631	     *
632	     * @example A projection that asks for everything leaves its rows alone
633	     *     $row = \App\Gql\Binding\BindingRow::unit()->with('p', new \App\Gql\Datum\IntegerDatum(1));
634	     *     $execution = new \App\Gql\Execution\ReturnExecution(new \App\Gql\Execution\RowExecution(new \App\Gql\Evaluation\ExpressionEvaluation()));
635	     *     $execution->reported(new \App\Gql\Syntax\Clause\ReturnClause(), new \App\Gql\Binding\BindingTable([$row]))[0]->value('p')->toText() // => '1'
636	     *
637	     * @return list<BindingRow> The rows
638	     *
639	     * @throws GqlException If a column cannot be worked out
640	     */
641	    public function reported(ReturnClause $clause, BindingTable $table): array
642	    {
643	        $evaluation = new ExpressionEvaluation();
644	        $produced = [];
645	        foreach ($table->rows as $row) {
646	            $values = [];
647	            foreach ($clause->columns as $column) {
648	                $values[$column->heading()] = $evaluation->evaluate($column->value, $row);
649	            }
650	            $produced[] = $row->withAll($values);
651	        }
652	
653	        return $produced;
654	    }
655	
656	    /**
657	     * Returns one row per group, with the summaries worked out over each group.
658	     *
659	     * @param ReturnClause $clause The clause
660	     * @param BindingTable $table  The rows it is given
661	     *
662	     * @example Summarising no rows at all still answers once
663	     *     $counted = new \App\Gql\Syntax\Expression\CallExpression('count', [], false, true);
664	     *     $clause = new \App\Gql\Syntax\Clause\ReturnClause([new \App\Gql\Syntax\Clause\Projection($counted, 'n', 'count(*)')]);
665	     *     $execution = new \App\Gql\Execution\ReturnExecution(new \App\Gql\Execution\RowExecution(new \App\Gql\Evaluation\ExpressionEvaluation()));
666	     *     count($execution->summarised($clause, \App\Gql\Binding\BindingTable::nothing())) // => 1
667	     *
668	     * @return list<BindingRow> The rows
669	     *
670	     * @throws GqlException If a column cannot be worked out
671	     */
672	    public function summarised(ReturnClause $clause, BindingTable $table): array
673	    {
674	        $produced = [];
675	        foreach (self::groups(self::groupKeys($clause), $table->rows) as $group) {
676	            $representative = $group[0] ?? BindingRow::unit();
677	            $over = ExpressionEvaluation::over($group);
678	            $values = [];
679	            foreach ($clause->columns as $column) {
680	                $values[$column->heading()] = $over->evaluate($column->value, $representative);
681	            }
682	            $produced[] = $representative->withAll($values);
683	        }
684	
685	        return $produced;
686	    }
