688	    /**
689	     * Returns what the rows are grouped by, with a named column read as what names it.
690	     *
691	     * GQL groups by names bound before the projection, which usually means names a
692	     * `LET` gave. Writing `GROUP BY kind` where `kind` is a column the same projection
693	     * names is the obvious thing to try, and refusing it would send a reader back to
694	     * add a `LET` that says nothing new — so a grouping key that names a column of
695	     * this projection is read as whatever that column shows.
696	     *
697	     * @param ReturnClause $clause The clause
698	     *
699	     * @example A grouping key that names a column of the projection is that column
700	     *     $shown = new \App\Gql\Syntax\Expression\PropertyExpression(new \App\Gql\Syntax\Expression\VariableExpression('p'), 'kind');
701	     *     $clause = new \App\Gql\Syntax\Clause\ReturnClause(
702	     *         [new \App\Gql\Syntax\Clause\Projection($shown, 'kind', 'p.kind')],
703	     *         false,
704	     *         [new \App\Gql\Syntax\Expression\VariableExpression('kind')],
705	     *     );
706	     *     \App\Gql\Execution\ReturnExecution::groupKeys($clause)[0] === $shown // => true
707	     *
708	     * @return list<Expression> What the rows are grouped by
709	     */
710	    public static function groupKeys(ReturnClause $clause): array
711	    {
712	        $named = [];
713	        foreach ($clause->columns as $column) {
714	            if ($column->alias !== null) {
715	                $named[$column->alias] = $column->value;
716	            }
717	        }
718	
719	        $keys = [];
720	        foreach ($clause->groupBy as $key) {
721	            $keys[] = $key instanceof VariableExpression ? $named[$key->name] ?? $key : $key;
722	        }
723	
724	        return $keys;
725	    }
