727	    /**
728	     * Returns the rows gathered into the groups they are summarised over.
729	     *
730	     * A projection with no grouping key makes one group of everything, including when
731	     * there is nothing — which is what makes a count over an empty result zero rather
732	     * than no answer at all.
733	     *
734	     * @param list<Expression> $keys The grouping keys
735	     * @param list<BindingRow> $rows The rows
736	     *
737	     * @example Grouping by nothing makes one group
738	     *     count(\App\Gql\Execution\ReturnExecution::groups([], [])) // => 1
739	     *
740	     * @return list<list<BindingRow>> The groups
741	     *
742	     * @throws GqlException If a grouping key cannot be worked out
743	     */
744	    public static function groups(array $keys, array $rows): array
745	    {
746	        if ($keys === []) {
747	            return [$rows];
748	        }
749	
750	        $evaluation = new ExpressionEvaluation();
751	        $groups = [];
752	        foreach ($rows as $row) {
753	            $values = [];
754	            foreach ($keys as $key) {
755	                $values[] = $evaluation->evaluate($key, $row);
756	            }
757	            $groups[DatumIdentity::keyOfAll($values)][] = $row;
758	        }
759	
760	        return array_values($groups);
761	    }
