763	    /**
764	     * Returns the rows with those that repeat shown once.
765	     *
766	     * Two rows repeat when the columns being shown are the same, whatever else the
767	     * rows carry: a projection of one property of two different symbols has two rows
768	     * and one distinct one.
769	     *
770	     * @param list<string>     $headings The columns being shown
771	     * @param list<BindingRow> $rows     The rows
772	     *
773	     * @example Rows that agree on what is shown are shown once
774	     *     $left = \App\Gql\Binding\BindingRow::unit()->with('n', new \App\Gql\Datum\IntegerDatum(1));
775	     *     $right = \App\Gql\Binding\BindingRow::unit()->with('n', new \App\Gql\Datum\IntegerDatum(1));
776	     *     count(\App\Gql\Execution\ReturnExecution::once(['n'], [$left, $right])) // => 1
777	     *
778	     * @return list<BindingRow> The rows, without repetition
779	     */
780	    public static function once(array $headings, array $rows): array
781	    {
782	        $seen = [];
783	        $kept = [];
784	        foreach ($rows as $row) {
785	            $values = [];
786	            foreach ($headings as $heading) {
787	                $values[] = $row->value($heading);
788	            }
789	            $key = DatumIdentity::keyOfAll($values);
790	            if (isset($seen[$key])) {
791	                continue;
792	            }
793	            $seen[$key] = true;
794	            $kept[] = $row;
795	        }
796	
797	        return $kept;
798	    }
