819	/**
820	 * The clauses that work on rows without touching the graph.
821	 *
822	 * Naming, filtering, ordering and paging are one class because they are one kind of
823	 * thing: each takes the rows it is given and hands back rows, with no reference to
824	 * what a pattern is or how a graph is walked. That separation is worth keeping — it
825	 * is the reason a query's shape is readable in the order it is written.
826	 *
827	 * @visibility App\Gql
828	 */
829	final class RowExecution
830	{
831	    /**
832	     * @param ExpressionEvaluation $evaluation How an expression is worked out for a row
833	     */
834	    public function __construct(
835	        private readonly ExpressionEvaluation $evaluation,
836	    ) {}
837	
838	    /**
839	     * Returns the rows a LET produces: the ones it was given, with more names bound.
840	     *
841	     * Every name in one clause is worked out from the row as it arrived, so none of
842	     * them can see another. That is GQL's rule, and it is why a value built from
843	     * another needs a clause of its own.
844	     *
845	     * @param LetClause    $clause The clause
846	     * @param BindingTable $table  The rows it is given
847	     *
848	     * @example A naming adds a column to every row it is given
849	     *     $parser = new \App\Gql\Parsing\ExpressionParser(\App\Gql\Parsing\TokenReader::of('1'));
850	     *     $binding = new \App\Gql\Syntax\Clause\VariableBinding('n', $parser->parse());
851	     *     $execution = new \App\Gql\Execution\RowExecution(new \App\Gql\Evaluation\ExpressionEvaluation());
852	     *     $execution->bind(new \App\Gql\Syntax\Clause\LetClause([$binding]), \App\Gql\Binding\BindingTable::unit())->names() // => ['n']
853	     *
854	     * @return BindingTable The rows it produces
855	     *
856	     * @throws GqlException If a named value cannot be worked out
857	     */
858	    public function bind(LetClause $clause, BindingTable $table): BindingTable
859	    {
860	        $produced = [];
861	        foreach ($table->rows as $row) {
862	            $bound = [];
863	            foreach ($clause->bindings as $binding) {
864	                $bound[$binding->name] = $this->evaluation->evaluate($binding->value, $row);
865	            }
866	            $produced[] = $row->withAll($bound);
867	        }
868	
869	        return new BindingTable($produced);
870	    }
871	
872	    /**
873	     * Returns the rows a FILTER keeps.
874	     *
875	     * Only the rows the predicate is true of survive. A row it is false of is
876	     * dropped, and so is a row it could not be decided for — which is what makes a
877	     * filter over a property some symbols do not carry narrow rather than widen.
878	     *
879	     * @param FilterClause $clause The clause
880	     * @param BindingTable $table  The rows it is given
881	     *
882	     * @example A predicate that cannot be decided keeps nothing
883	     *     $parser = new \App\Gql\Parsing\ExpressionParser(\App\Gql\Parsing\TokenReader::of('NULL'));
884	     *     $execution = new \App\Gql\Execution\RowExecution(new \App\Gql\Evaluation\ExpressionEvaluation());
885	     *     $execution->keep(new \App\Gql\Syntax\Clause\FilterClause($parser->parse()), \App\Gql\Binding\BindingTable::unit())->rows // => []
886	     *
887	     * @return BindingTable The rows it keeps
888	     *
889	     * @throws GqlException If the predicate cannot be worked out, or is not a predicate
890	     */
891	    public function keep(FilterClause $clause, BindingTable $table): BindingTable
892	    {
893	        $kept = [];
894	        foreach ($table->rows as $row) {
895	            if (Logic::holds($this->evaluation->evaluate($clause->predicate, $row))) {
896	                $kept[] = $row;
897	            }
898	        }
899	
900	        return new BindingTable($kept);
901	    }
902	
903	    /**
904	     * Returns the rows an ORDER BY produces, in the order it asks for.
905	     *
906	     * @param OrderByClause $clause The clause
907	     * @param BindingTable  $table  The rows it is given
908	     *
909	     * @example Ordering nothing produces nothing
910	     *     $parser = new \App\Gql\Parsing\ExpressionParser(\App\Gql\Parsing\TokenReader::of('1'));
911	     *     $key = new \App\Gql\Syntax\Clause\SortKey($parser->parse());
912	     *     $execution = new \App\Gql\Execution\RowExecution(new \App\Gql\Evaluation\ExpressionEvaluation());
913	     *     $execution->order(new \App\Gql\Syntax\Clause\OrderByClause([$key]), \App\Gql\Binding\BindingTable::nothing())->rows // => []
914	     *
915	     * @return BindingTable The rows, ordered
916	     *
917	     * @throws GqlException If a sort key cannot be worked out
918	     */
919	    public function order(OrderByClause $clause, BindingTable $table): BindingTable
920	    {
921	        return new BindingTable($this->sorted($clause->keys, $table->rows));
922	    }
923	
924	    /**
925	     * Returns rows put in the order a list of sort keys asks for.
926	     *
927	     * The keys are worked out once per row rather than on every comparison, which
928	     * matters on a query that sorts by something expensive — a path length, a
929	     * concatenation of names.
930	     *
931	     * @param list<SortKey>    $keys The keys, most significant first
932	     * @param list<BindingRow> $rows The rows
933	     *
934	     * @example Ordering no rows produces no rows
935	     *     (new \App\Gql\Execution\RowExecution(new \App\Gql\Evaluation\ExpressionEvaluation()))->sorted([], []) // => []
936	     *
937	     * @return list<BindingRow> The rows, ordered
938	     *
939	     * @throws GqlException If a sort key cannot be worked out
940	     */
941	    public function sorted(array $keys, array $rows): array
942	    {
943	        $keyed = [];
944	        foreach ($rows as $index => $row) {
945	            $values = [];
946	            foreach ($keys as $key) {
947	                $values[] = $this->evaluation->evaluate($key->value, $row);
948	            }
949	            $keyed[] = ['row' => $row, 'values' => $values, 'index' => $index];
950	        }
951	
952	        usort($keyed, static fn (array $left, array $right): int => self::against($keys, $left, $right));
953	
954	        return array_map(static fn (array $entry): BindingRow => $entry['row'], $keyed);
955	    }
956	
957	    /**
958	     * Compares two rows by their sort keys, most significant first.
959	     *
960	     * @param list<SortKey>                                           $keys  The keys, most significant first
961	     * @param array{row: BindingRow, values: list<Datum>, index: int} $left  The row on the left
962	     * @param array{row: BindingRow, values: list<Datum>, index: int} $right The row on the right
963	     *
964	     * @example Rows that tie on every key keep the order they arrived in
965	     *     $left = ['row' => \App\Gql\Binding\BindingRow::unit(), 'values' => [], 'index' => 0];
966	     *     $right = ['row' => \App\Gql\Binding\BindingRow::unit(), 'values' => [], 'index' => 1];
967	     *     \App\Gql\Execution\RowExecution::against([], $left, $right) // => -1
968	     *
969	     * @return int Negative, zero or positive
970	     *
971	     * @throws GqlException If a key holds two values GQL gives no order between
972	     */
973	    public static function against(array $keys, array $left, array $right): int
974	    {
975	        foreach ($keys as $place => $key) {
976	            $order = DatumOrder::sort($left['values'][$place], $right['values'][$place]) * $key->direction->factor();
977	            if ($order !== 0) {
978	                return $order;
979	            }
980	        }
981	
982	        return $left['index'] <=> $right['index'];
983	    }
984	
985	    /**
986	     * Returns the stretch of rows a page asks for.
987	     *
988	     * @param PageClause   $clause The clause
989	     * @param BindingTable $table  The rows it is given
990	     *
991	     * @example A page that keeps nothing keeps nothing
992	     *     $execution = new \App\Gql\Execution\RowExecution(new \App\Gql\Evaluation\ExpressionEvaluation());
993	     *     $execution->page(new \App\Gql\Syntax\Clause\PageClause(0, 0), \App\Gql\Binding\BindingTable::unit())->rows // => []
994	     *
995	     * @return BindingTable The stretch
996	     */
997	    public function page(PageClause $clause, BindingTable $table): BindingTable
998	    {
999	        return new BindingTable(array_slice($table->rows, $clause->offset, $clause->limit));
1000	    }
