1008	use App\Gql\Datum\DatumIdentity;
1009	use App\Gql\GqlException;
1010	use App\Gql\Result\ResultRow;
1011	use App\Gql\Result\ResultTable;
1012	use App\Gql\StatusCode;
1013	use App\Gql\Syntax\SetOperator;
1014	
1015	/**
1016	 * Combining what two runs of clauses answered.
1017	 *
1018	 * Set operations are how one query asks a question with two shapes: "everything that
1019	 * reaches this class, whether by calling it or by extending it" is two patterns and
1020	 * one answer. The difference and the intersection are the ones a question about
1021	 * layering reaches for — what the controllers reach that the domain does not.
1022	 *
1023	 * Both sides must have the same number of columns, because a row of one has to be a
1024	 * row of the other for any of this to mean anything. The headings are taken from the
1025	 * left, which is the side a reader wrote first.
1026	 *
1027	 * @visibility App\Gql
1028	 */
1029	final class SetOperation
1030	{
1031	    /**
1032	     * Returns the two results combined.
1033	     *
1034	     * @param SetOperator $operator How to combine them
1035	     * @param ResultTable $left     What the run on the left answered
1036	     * @param ResultTable $right    What the run on the right answered
1037	     *
1038	     * @example Keeping everything keeps the rows of both
1039	     *     $row = new \App\Gql\Result\ResultRow([new \App\Gql\Datum\IntegerDatum(1)]);
1040	     *     $column = [new \App\Gql\Result\ResultColumn('n', 'INT64')];
1041	     *     $table = new \App\Gql\Result\ResultTable($column, [$row]);
1042	     *     count(\App\Gql\Execution\SetOperation::combine(\App\Gql\Syntax\SetOperator::UnionAll, $table, $table)->rows) // => 2
1043	     * @example Dropping what repeats keeps one of them
1044	     *     $row = new \App\Gql\Result\ResultRow([new \App\Gql\Datum\IntegerDatum(1)]);
1045	     *     $column = [new \App\Gql\Result\ResultColumn('n', 'INT64')];
1046	     *     $table = new \App\Gql\Result\ResultTable($column, [$row]);
1047	     *     count(\App\Gql\Execution\SetOperation::combine(\App\Gql\Syntax\SetOperator::Union, $table, $table)->rows) // => 1
1048	     *
1049	     * @return ResultTable The two combined
1050	     *
1051	     * @throws GqlException If the two sides do not have the same number of columns
1052	     */
1053	    public static function combine(SetOperator $operator, ResultTable $left, ResultTable $right): ResultTable
1054	    {
1055	        if ($operator === SetOperator::Otherwise) {
1056	            return $left->rows === [] ? $right : $left;
1057	        }
1058	        self::requireSameShape($left, $right);
1059	        if ($operator === SetOperator::UnionAll) {
1060	            return new ResultTable($left->columns, [...$left->rows, ...$right->rows]);
1061	        }
1062	        if ($operator === SetOperator::Union) {
1063	            return new ResultTable($left->columns, self::once([...$left->rows, ...$right->rows]));
1064	        }
1065	
1066	        return new ResultTable(
1067	            $left->columns,
1068	            self::once(self::sharing($left->rows, $right->rows, $operator === SetOperator::Intersect)),
1069	        );
1070	    }
1071	
1072	    /**
1073	     * Reports two results that cannot be combined as the mistake they are.
1074	     *
1075	     * @param ResultTable $left  What the run on the left answered
1076	     * @param ResultTable $right What the run on the right answered
1077	     *
1078	     * @example Two results of the same shape pass without comment
1079	     *     $table = new \App\Gql\Result\ResultTable([new \App\Gql\Result\ResultColumn('n', 'INT64')], []);
1080	     *     \App\Gql\Execution\SetOperation::requireSameShape($table, $table) // => null
1081	     * @example Two of different shapes are reported rather than lined up
1082	     *     $left = new \App\Gql\Result\ResultTable([new \App\Gql\Result\ResultColumn('n', 'INT64')], []);
1083	     *     \App\Gql\Execution\SetOperation::requireSameShape($left, \App\Gql\Result\ResultTable::nothing()) // throws \App\Gql\GqlException: syntax error
1084	     *
1085	     * @throws GqlException If the two sides do not have the same number of columns
1086	     */
1087	    public static function requireSameShape(ResultTable $left, ResultTable $right): void
1088	    {
1089	        if (count($left->columns) === count($right->columns)) {
1090	            return;
1091	        }
1092	
1093	        throw GqlException::because(
1094	            StatusCode::SyntaxError,
1095	            sprintf(
1096	                'two results can only be combined when they have the same columns, and these have %d and %d',
1097	                count($left->columns),
1098	                count($right->columns),
1099	            ),
1100	        );
1101	    }
1102	
1103	    /**
1104	     * Returns the rows with those that repeat shown once.
1105	     *
1106	     * @param list<ResultRow> $rows The rows
1107	     *
1108	     * @example Rows that hold the same values are shown once
1109	     *     $rows = [new \App\Gql\Result\ResultRow([new \App\Gql\Datum\IntegerDatum(1)]), new \App\Gql\Result\ResultRow([new \App\Gql\Datum\IntegerDatum(1)])];
1110	     *     count(\App\Gql\Execution\SetOperation::once($rows)) // => 1
1111	     *
1112	     * @return list<ResultRow> The rows, without repetition
1113	     */
1114	    public static function once(array $rows): array
1115	    {
1116	        $seen = [];
1117	        $kept = [];
1118	        foreach ($rows as $row) {
1119	            $key = DatumIdentity::keyOfAll($row->values);
1120	            if (isset($seen[$key])) {
1121	                continue;
1122	            }
1123	            $seen[$key] = true;
1124	            $kept[] = $row;
1125	        }
1126	
1127	        return $kept;
1128	    }
1129	
1130	    /**
1131	     * Returns the rows of one side that the other side does or does not also have.
1132	     *
1133	     * @param list<ResultRow> $left   The rows on the left
1134	     * @param list<ResultRow> $right  The rows on the right
1135	     * @param bool            $shared Whether to keep the rows both sides have, rather than the rest
1136	     *
1137	     * @example The rows both sides have
1138	     *     $row = new \App\Gql\Result\ResultRow([new \App\Gql\Datum\IntegerDatum(1)]);
1139	     *     count(\App\Gql\Execution\SetOperation::sharing([$row], [$row], true)) // => 1
1140	     * @example The rows only the left side has
1141	     *     $row = new \App\Gql\Result\ResultRow([new \App\Gql\Datum\IntegerDatum(1)]);
1142	     *     \App\Gql\Execution\SetOperation::sharing([$row], [$row], false) // => []
1143	     *
1144	     * @return list<ResultRow> The rows kept
1145	     */
1146	    public static function sharing(array $left, array $right, bool $shared): array
1147	    {
1148	        $known = [];
1149	        foreach ($right as $row) {
1150	            $known[DatumIdentity::keyOfAll($row->values)] = true;
1151	        }
1152	
1153	        $kept = [];
1154	        foreach ($left as $row) {
1155	            if (isset($known[DatumIdentity::keyOfAll($row->values)]) === $shared) {
1156	                $kept[] = $row;
1157	            }
1158	        }
1159	
1160	        return $kept;
1161	    }
1162	}
