final class QueryExecutionTest extends TestCase
{
    /**
     * @throws GqlException
     */
    public function testAgainstQueriesTheGraphAnalysisProduced(): void
    {
        $answered = QueryExecution::against(SampleGraph::analysed())->query('MATCH (p:Class) RETURN p.name AS name ORDER BY name');

        self::assertSame('[name:STRING] Controller; Invoice; Kernel; Store', AnsweredQuery::written($answered));
    }

    /**
     * @throws GqlException
     */
    public function testQueryReadsAQueryAndRunsIt(): void
    {
        self::assertSame('[n:INT64] 1', AnsweredQuery::of('RETURN 1 AS n'));
    }

    /**
     * @throws GqlException
     */
    public function testQuerySaysThatItFoundNothingRatherThanFailing(): void
    {
        self::assertSame(StatusCode::NoData, AnsweredQuery::table('MATCH (p:Interface) RETURN p')->status());
    }

    /**
     * @throws GqlException
     */
    public function testQueryReportsAQueryThatCannotBeRead(): void
    {
        $this->expectException(GqlException::class);
        $this->expectExceptionMessage('expected a RETURN statement');

        AnsweredQuery::of('MATCH (p) RETRUN p');
    }

    /**
     * @throws GqlException
     */
    public function testRunAnswersWithBothSidesOfAQueryThatCombinesTwoRuns(): void
    {
        self::assertSame('[n:INT64] 1; 2', AnsweredQuery::of('RETURN 1 AS n UNION ALL RETURN 2 AS n'));
    }

    /**
     * @throws GqlException
     */
    public function testRunGoesNoFurtherThanTheHopLimitItWasGiven(): void
    {
        $answered = AnsweredQuery::table(
            "MATCH (a:Method WHERE a.name = 'show')-[:methodCall]->{1,}(b:Method) RETURN b.name AS name",
            1,
        );

        self::assertSame('[name:STRING] total', AnsweredQuery::written($answered));
    }
}
