#[UsesClass(SetOperator::class)]
#[UsesClass(BlockExecution::class)]
#[UsesClass(MatchExecution::class)]
#[UsesClass(QueryExecution::class)]
#[UsesClass(ReturnExecution::class)]
#[UsesClass(RowExecution::class)]
#[Small]
final class SetOperationTest extends TestCase
{
    /**
     * @throws GqlException
     */
    #[DataProvider('providerOperatorsAndWhatTheyCombine')]
    public function testCombineCombinesWhatTwoRunsAnswered(string $query, string $expected): void
    {
        self::assertSame($expected, AnsweredQuery::of($query));
    }

    /**
     * @return iterable<string, array{string, string}>
     */
    public static function providerOperatorsAndWhatTheyCombine(): iterable
    {
        yield 'keeping every row of both' => ['RETURN 1 AS n UNION ALL RETURN 1 AS n', '[n:INT64] 1; 1'];

        yield 'dropping what repeats' => ['RETURN 1 AS n UNION RETURN 1 AS n', '[n:INT64] 1'];

        yield 'keeping what both sides have' => ['RETURN 1 AS n INTERSECT RETURN 1 AS n', '[n:INT64] 1'];

        yield 'keeping what only the left has' => ['RETURN 1 AS n EXCEPT RETURN 1 AS n', '[n:INT64] '];

        yield 'keeping what only the left has, when the right has none of it' => [
            'RETURN 1 AS n EXCEPT RETURN 2 AS n',
            '[n:INT64] 1',
        ];

        yield 'falling back only when the left found nothing' => [
            'MATCH (p:Interface) RETURN p.name AS name OTHERWISE RETURN 1 AS name',
            '[name:INT64] 1',
        ];

        yield 'not falling back when the left found something' => [
            'RETURN 1 AS n OTHERWISE RETURN 2 AS n',
            '[n:INT64] 1',
        ];
    }

    /**
     * @throws GqlException
     */
    public function testCombineAnswersTwoPatternsAsOneQuestion(): void
    {
        self::assertSame(
            '[reaching:STRING] show; store; total; Controller',
            AnsweredQuery::of(
                'MATCH (a:Method)-[:methodCall]->(b) RETURN a.name AS reaching'
                .' UNION MATCH (c:Class)-[:extends]->(d) RETURN c.name AS reaching',
            ),
        );
    }

    /**
     * @throws GqlException
     */
    public function testRequireSameShapeAcceptsTwoResultsOfTheSameShape(): void
    {
        $table = new ResultTable([new ResultColumn('n', 'INT64')], []);

        SetOperation::requireSameShape($table, $table);

        self::assertCount(1, $table->columns);
    }

    /**
     * @throws GqlException
     */
    public function testRequireSameShapeReportsTwoResultsThatCannotBeLinedUp(): void
    {
        $this->expectException(GqlException::class);
        $this->expectExceptionMessage('two results can only be combined when they have the same columns, and these have 1 and 0');

        SetOperation::requireSameShape(new ResultTable([new ResultColumn('n', 'INT64')], []), ResultTable::nothing());
    }

    public function testOnceShowsRowsHoldingTheSameValuesOnlyOnce(): void
    {
        $rows = [new ResultRow([new IntegerDatum(1)]), new ResultRow([new IntegerDatum(1)])];

        self::assertCount(1, SetOperation::once($rows));
    }

    public function testSharingKeepsTheRowsBothSidesHave(): void
    {
        $row = new ResultRow([new IntegerDatum(1)]);

        self::assertCount(1, SetOperation::sharing([$row], [$row], true));
    }

    public function testSharingKeepsTheRowsOnlyOneSideHas(): void
    {
        $row = new ResultRow([new IntegerDatum(1)]);

        self::assertSame([], SetOperation::sharing([$row], [$row], false));
    }
}
